#define BEEBO_CMD_NODE_DISCOVER                     243  // actively query nearby nodes for their identity, rather than waiting on their next periodic self-advert (CTL_TYPE_NODE_DISCOVER_REQ/RESP, see Beebo::sendNodeDiscoverReq()). payload: [filter:1][prefix_only:1]; filter is a bitmask of (1 << ADV_TYPE_*) -- e.g. (1<<ADV_TYPE_REPEATER)|(1<<ADV_TYPE_SENSOR) to ask for repeaters and sensors -- ERR_CODE_ILLEGAL_ARG if 0; prefix_only=1 asks responders to reply with only an 8-byte pubkey prefix instead of the full 32 bytes. Replies OK immediately (the request is a zero-hop broadcast, sent and forgotten); matching CTL_TYPE_NODE_DISCOVER_RESP replies trickle in over the following ~60s and are logged into the existing direct (zero-hop) neighbour table (Beebo::putNeighbour()), same as GET_NEIGHBORS already streams -- poll that command after a short wait to see results. Not role-gated: any role can ask 'who's near me'; only nodes whose own current type matches a set filter bit answer (CTL_TYPE_NODE_DISCOVER_REQ handling in onControlDataRecv(), also not role-gated -- a companion node answers as ADV_TYPE_CHAT, a repeater as ADV_TYPE_REPEATER). Mirrors CommonCLI's text-CLI 'discover.neighbors [repeater|chat|room|sensor|all ...]'
#define BEEBO_CMD_GET_ADVERT_PATHS                  244  // stream the WHOLE advert_paths[] cache (ADVERT_PATH_TABLE_SIZE=16 entries, LRU by recv_timestamp) in one round trip, no payload -- the bulk counterpart to upstream's single-pubkey CMD_GET_ADVERT_PATH (0x2a). Match each entry's pubkey_prefix locally against however many contacts the caller cares about instead of issuing one CMD_GET_ADVERT_PATH per contact: the cache only ever holds 16 entries total regardless of contact-list size, so a per-contact loop is always doing 16 real answers' worth of work spread over however many round trips there are contacts, for no benefit over one bulk read. Same START/entry/END streaming shape as GET_NEIGHBORS
#define BEEBO_CMD_GET_PUBLIC_KEY                    245  // payload: 1 byte role (NODE_ROLE_COMPANION=0/NODE_ROLE_REPEATER=1); reply RESP_CODE_BEEBO/PUBLIC_KEY with that role's own 32-byte Ed25519 public key, regardless of which role is currently live (PER_ROLE_IDENTITY plan) -- self_info only ever reflects the live role's identity, so companion.public_key/repeater.public_key settings leaves read through this instead. ERR_CODE_ILLEGAL_ARG if role isn't 0/1; ERR_CODE_NOT_FOUND if that role has never been switched into on this device yet (its identity file doesn't exist) -- a GET must never have the side effect of creating one
#define BEEBO_CMD_GET_BOARD_ID                      246  // no payload; reply RESP_CODE_BEEBO/BOARD_ID with the ESP32's 6-byte factory eFuse base MAC (esp_efuse_mac_get_default()) -- a hardware-burned identifier, stable across reflashes/identity changes/role switches, independent of node.public_key (ed25519, unrelated to the MAC) and of node.role (shared across both). Not a wire MAC address (no per-interface offset applied, see esp_read_mac()), just a unique per-board ID
#define BEEBO_CMD_GET_BOARD_NAME                    251  // no payload; reply RESP_CODE_BEEBO/BOARD_NAME with BeeboCompanionPrefs.board_name bytes (no NUL, may be empty). Human-editable alias for this physical board's identity (board.id, the read-only eFuse MAC) -- distinct from the per-role persona names (companion.name/repeater.name, see GET_ROLE_NAME): board.name identifies the hardware, not a role. Role-agnostic -- BeeboCompanionPrefs is compiled into every build (multi_role, static companion, static repeater), same as owner_password. Empty until the operator sets one (see beebo/plans/DEVICE_NAME.md); `beebo config`'s default filenames fall back to board.id's hex string until then
#define BEEBO_CMD_SET_BOARD_NAME                    252  // payload: name string bytes (no NUL, up to 31); updates RAM + BeeboCompanionPrefs.board_name. Purely a local label -- unlike node.owner.password this has no gating/security role, it's just a friendlier name than board.id's raw hex for a human to recognize the device by
#define BEEBO_CMD_SET_OWNER_PASSWORD                248  // payload: password string bytes (no NUL, up to 15); write-only, updates RAM + BeeboCompanionPrefs.owner_password. Role-agnostic -- BeeboCompanionPrefs is compiled into every build (multi_role, static companion, static repeater), unlike ComPrefs/repeater.password which only exists when BEEBO_ENABLE_REPEATER_ROLE=1. This is the node's one backup/recovery credential (see UNLOCK_ROLE_SECRETS below), distinct from repeater.password (mesh admin login, only meaningful when the repeater role is actually compiled in)
#define BEEBO_CMD_GET_OWNER_PASSWORD_SET            249  // reply OK + value (4B LE) = 1 if node.owner.password has ever been set (non-empty), 0 if still unset -- unlike repeater.password there's no compiled-in default to compare against (empty is the only unset state); never the password itself
#define BEEBO_CMD_GET_ROLE_NAME                     250  // payload: 1 byte role (NODE_ROLE_COMPANION=0/NODE_ROLE_REPEATER=1); reply RESP_CODE_BEEBO/ROLE_NAME with that role's own name, regardless of which role is currently live -- reads that role's own resident role_state_store[] slot directly (never the live role's slot), mirrors GET_PUBLIC_KEY. NODE_ROLE_COMPANION replies NodePrefs.node_name; NODE_ROLE_REPEATER replies ComPrefs.node_name; empty if that role's name was never set, no fallback between roles. companion.name/repeater.name settings leaves and anything else that needs a role's own name irrespective of what's live (`beebo config pull/diff/push --role`, ...) read through here -- RESP_CODE_SELF_INFO's own "name" field is live-role-scoped (swaps with type/pubkey per GET_NODE_ROLE's hot-switch, see that reply's own comment), so it's only correct for whichever role is actually live, not an arbitrary target role. Always succeeds for either role (unlike GET_PUBLIC_KEY, a name isn't gated on that role's identity having ever been created). ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_GET_MULTI_ACKS                     27  // payload: 1 byte role (NODE_ROLE_COMPANION=0/NODE_ROLE_REPEATER=1); reply OK + value (4B LE, 0/1) = that role's own multi_acks, regardless of which role is currently live -- same GET_ROLE_NAME-style role-parameterized shape, calling the same tlvGetMultiAcks(role) backend the now-retired GET_COMPANION_MULTI_ACKS/GET_REPEATER_MULTI_ACKS opcodes used to wrap directly. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_SET_MULTI_ACKS                     28  // payload: 1 byte role, then 4B LE value (0/1, clamped); writes that role's own multi_acks directly via tlvSetMultiAcks(role, ...) -- replaces the retired SET_COMPANION_MULTI_ACKS/SET_REPEATER_MULTI_ACKS. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_GET_PATH_HASH_MODE                 29  // payload: 1 byte role; reply OK + value (4B LE, 0-2) = that role's own path_hash_mode, via tlvGetPathHashMode(role) -- replaces the retired GET_COMPANION_PATH_HASH_MODE/GET_REPEATER_PATH_HASH_MODE. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_SET_PATH_HASH_MODE                 30  // payload: 1 byte role, then 4B LE value (0-2); writes that role's own path_hash_mode via tlvSetPathHashMode(role, ...) -- replaces the retired SET_COMPANION_PATH_HASH_MODE/SET_REPEATER_PATH_HASH_MODE. ERR_CODE_ILLEGAL_ARG if role isn't 0/1 or value >=3
#define BEEBO_CMD_GET_LAT                            31  // payload: 1 byte role; reply OK + value (4B LE, signed int32 degrees*1e6) = that role's own PREFS-mode node_lat, via tlvGetLat(role) -- replaces the retired GET_COMPANION_LAT/GET_REPEATER_LAT. Paired with GET_ROLE_LON the same way the legacy per-role opcodes are paired, not a combined coords opcode. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_SET_LAT                            32  // payload: 1 byte role, then 4B LE signed int32 degrees*1e6; writes that role's own node_lat via tlvSetLat(role, ...) -- replaces the retired SET_COMPANION_LAT/SET_REPEATER_LAT. ERR_CODE_ILLEGAL_ARG if role isn't 0/1 or value out of [-90e6, 90e6]
#define BEEBO_CMD_GET_LON                            33  // payload: 1 byte role; reply OK + value (4B LE, signed int32 degrees*1e6) = that role's own node_lon, via tlvGetLon(role) -- replaces the retired GET_COMPANION_LON/GET_REPEATER_LON. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_SET_LON                            34  // payload: 1 byte role, then 4B LE signed int32 degrees*1e6; writes that role's own node_lon via tlvSetLon(role, ...) -- replaces the retired SET_COMPANION_LON/SET_REPEATER_LON. ERR_CODE_ILLEGAL_ARG if role isn't 0/1 or value out of [-180e6, 180e6]
#define BEEBO_CMD_GET_ADV_LOC_POLICY                 35  // payload: 1 byte role; reply OK + value (4B LE, 0-2) = that role's own advert_loc_policy, via tlvGetAdvLocPolicy(role) -- replaces the retired GET_COMPANION_ADV_LOC_POLICY/GET_REPEATER_ADV_LOC_POLICY. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_SET_ADV_LOC_POLICY                 36  // payload: 1 byte role, then 4B LE value (0-2); writes that role's own advert_loc_policy via tlvSetAdvLocPolicy(role, ...) -- replaces the retired SET_COMPANION_ADV_LOC_POLICY/SET_REPEATER_ADV_LOC_POLICY. ERR_CODE_ILLEGAL_ARG if role isn't 0/1 or value >=3
#define BEEBO_CMD_SET_NAME                           37  // payload: 1 byte role, then name string bytes (no NUL, up to 31); writes that role's own resident name directly via tlvSetName(role, ...) -- replaces the retired SET_COMPANION_NAME/SET_REPEATER_NAME. GET_ROLE_NAME (above) already covers the read side for both roles. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_GET_ROLE_TRANSPORT_CONFIG          38  // payload: 1 byte role; reply OK + value (byte0=ble_enabled, byte1=tcp_enabled, byte2=usb_enabled) = that role's own independent transport-enable flags, via tlvGetTransportConfig(role) -- replaces the retired GET_COMPANION_TRANSPORT_CONFIG/GET_REPEATER_TRANSPORT_CONFIG. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_SET_ROLE_TRANSPORT_CONFIG          39  // payload: 1 byte role, then [ble_enabled][tcp_enabled][usb_enabled] (no reboot byte -- a non-live target role has no reboot-to-apply meaning); writes via tlvSetTransportConfig(role, ...) -- replaces the retired SET_COMPANION_TRANSPORT_CONFIG/SET_REPEATER_TRANSPORT_CONFIG. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_GET_ROLE_WIFI_SSID                 40  // payload: 1 byte role; reply RESP_CODE_BEEBO/WIFI_SSID = that role's own independent wifi_ssid, via tlvGetWifiSsid(role) -- replaces the retired GET_COMPANION_WIFI_SSID/GET_REPEATER_WIFI_SSID. Distinct from the live-role-scoped bare GET_WIFI_SSID above (node.wifi.ssid). ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_SET_WIFI_SSID                      41  // payload: 1 byte role, then ssid bytes (no NUL); writes that role's own wifi_ssid only, via tlvSetWifiSsid(role, ...) -- leaves that role's wifi_pwd untouched (see SET_ROLE_WIFI_PWD/SET_ROLE_WIFI_CREDS for the password side). No prior per-role opcode set ssid alone; previously only reachable via the combined SET_COMPANION_WIFI_CREDS/SET_REPEATER_WIFI_CREDS payload with an empty password segment. Live-applies (starts WiFi) only if role is also the currently-live role. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_GET_ROLE_WIFI_PWD_SET              42  // payload: 1 byte role; reply OK + value (4B LE) = 1 if that role's own wifi_pwd is non-empty, 0 otherwise, via tlvGetWifiPwdSet(role) -- replaces the retired GET_COMPANION_WIFI_PWD_SET/GET_REPEATER_WIFI_PWD_SET; never the password itself. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_SET_WIFI_PWD                       43  // payload: 1 byte role, then password bytes (no NUL); writes that role's own wifi_pwd only, via tlvSetWifiPwd(role, ...) -- leaves that role's wifi_ssid untouched, same independent-field split as SET_ROLE_WIFI_SSID. Live-applies (starts WiFi) only if role is also the currently-live role. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_SET_ROLE_WIFI_CREDS                44  // payload: 1 byte role, then ssid\0pwd\0 (empty segment = leave unchanged); writes that role's own wifi_ssid/wifi_pwd via tlvSetWifiCreds(role, ...) -- replaces the retired SET_COMPANION_WIFI_CREDS/SET_REPEATER_WIFI_CREDS. Live-applies only if role is also the currently-live role. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_GET_BLE_PIN                        45  // payload: 1 byte role; reply OK + value (4B LE) = that role's own stored ble_pin override (0 = unset), via tlvGetBlePin(role) -- replaces the retired GET_COMPANION_BLE_PIN/GET_REPEATER_BLE_PIN; the *stored* value, not the resolved *active* session pin. ERR_CODE_ILLEGAL_ARG if role isn't 0/1
#define BEEBO_CMD_SET_BLE_PIN                        46  // payload: 1 byte role, then 4B LE value -- 0 (unset) or a 6-digit pin (100000-999999); writes via tlvSetBlePin(role, ...) -- replaces the retired SET_COMPANION_BLE_PIN/SET_REPEATER_BLE_PIN. Live-applies only if role is also the currently-live role. ERR_CODE_ILLEGAL_ARG if role isn't 0/1 or pin out of range
#define BEEBO_CMD_SET_COMPANION_MANUAL_ADD_CONTACTS  25  // payload: 1 byte (0/1); writes companion's own resident role_state_store[NODE_ROLE_COMPANION].prefs.manual_add_contacts directly, regardless of which role is currently live -- same bug-fix rationale as SET_NAME (manual_add_contacts had no dedicated GET either, since RESP_CODE_SELF_INFO's own field is only wrong while repeater is live and this leaf has no repeater-side twin to confuse it with, but the SET side still needed a role-explicit opcode). CMD_SET_OTHER_PARAMS keeps its existing live-role-targeting semantics unchanged; companion.manual_add_contacts (prefs.py) now calls this instead
#define BEEBO_CMD_SET_COMPANION_AUTOADD_CONFIG       26  // payload: 1 byte bitmask (autoadd_max_hops left unchanged); writes companion's own resident role_state_store[NODE_ROLE_COMPANION].prefs.autoadd_config directly, regardless of which role is currently live -- same bug-fix rationale as SET_COMPANION_MANUAL_ADD_CONTACTS. CMD_SET_AUTOADD_CONFIG keeps its existing live-role-targeting semantics unchanged; companion.autoadd_config (prefs.py) now calls this instead
#define BEEBO_CMD_UNLOCK_ROLE_SECRETS               247  // payload: [candidate password bytes, up to 15, no NUL] -- checked against BeeboCompanionPrefs.owner_password (see SET_OWNER_PASSWORD), the node's single role-agnostic backup credential, present on every build regardless of which role(s) are compiled in. A mismatch AND an unset (empty) owner_password both fail closed -- unlocking is never possible until the owner has explicitly set this password at least once. Password-gated secret readback for `beebo config backup` (see beebo/plans/SETTINGS_ISOLATION.md): proves the caller already knows the owner password rather than exposing anything to a bare-reachable, unauthenticated session (multi_role's WiFi/TCP companion transport has no other authentication at all, unlike BLE's paired PIN or USB's physical possession -- this keeps a WiFi-only attacker from harvesting secrets they don't already know). On match, replies RESP_CODE_BEEBO/ROLE_SECRETS with repeater.guest.password + NUL + node.wifi.password + NUL + repeater.password, always in that order (any may be empty; the two repeater-only fields are always empty on a BEEBO_ENABLE_REPEATER_ROLE=0 build, which has no ComPrefs at all) -- one verified owner password unlocks every secret on the device, no separate proof needed per secret, since a session that already knows the owner password already has unrestricted write access to all of them (a companion session can already overwrite any of them blind, with no gate at all) -- reading their current values back is a strictly smaller exposure than that existing write access. A plain EventType.ERROR reply (not a distinct error code -- deliberately indistinguishable from a malformed request) on a mismatched/unset candidate, so a failed guess doesn't confirm anything about the real password's shape/length beyond what a normal login attempt already would. Available on every build, static or dynamic -- no ERR_CODE_UNSUPPORTED_CMD case anymore

// beebo response sub-ids (payload byte 0 after RESP_CODE_BEEBO)
#define BEEBO_RESP_OTA_BEGIN           200  // response to OTA_BEGIN
#define BEEBO_RESP_NEIGHBORS_START     201  // first reply to GET_NEIGHBORS: count + node time
#define BEEBO_RESP_NEIGHBOR            202  // one per direct neighbour
#define BEEBO_RESP_END_OF_NEIGHBORS    203  // last reply to GET_NEIGHBORS
#define BEEBO_RESP_MONRING             204  // reply to GET_MONRING: status header + records. Header's trailing reset:1 byte is 1 if the request's after_seq was overridden (after_ts predated the ring's current oldest resident record) and the reply starts from the oldest record instead, 0 if honored as given
#define BEEBO_RESP_XFER_CAPS           205  // (BULK_XFER): reply to SET_XFER_CAPS: granted [max_tx:2 LE][stream:1]
#define BEEBO_RESP_WIFI_SSID           206  // reply to GET_WIFI_SSID: ssid bytes (no NUL)
#define BEEBO_RESP_OWNER_INFO          207  // reply to GET_OWNER_INFO: owner info bytes (no NUL)
#define BEEBO_RESP_FULL_VERSION        208  // reply to GET_FULL_VERSION: untruncated FIRMWARE_VERSION bytes (no NUL)
#define BEEBO_RESP_PREFS_TLV           210  // reply to GET_PREFS_TLV: TLV triplets, see that command's desc
#define BEEBO_RESP_ACK_STATS           211  // reply to GET_ACK_STATS: ack_success_count (4B u32 LE) + ack_timeout_count (4B u32 LE) + ack_overflow_count (4B u32 LE)
#define BEEBO_RESP_ECHO_STATS          212  // reply to GET_ECHO_COUNT: echo_success_count (4B u32 LE) + echo_timeout_count (4B u32 LE) + echo_overflow_count (4B u32 LE) + self_tx_direct_count (4B u32 LE)
#define BEEBO_RESP_REGION_HOME         213  // reply to GET_REGION_HOME: home region name bytes (no NUL, may be empty)
#define BEEBO_RESP_REGION_LIST         214  // reply to GET_REGION_LIST: comma-separated region name bytes (no NUL, may be empty)
#define BEEBO_RESP_REGION_TREE         215  // reply to GET_REGION_TREE: RegionMap::exportTo()'s hierarchical text export bytes (no NUL, may be empty)
#define BEEBO_RESP_ADVERT_PATHS_START  216  // first reply to GET_ADVERT_PATHS: count of populated advert_paths[] entries (4B LE)
#define BEEBO_RESP_ADVERT_PATH         217  // one per populated advert_paths[] entry: pubkey_prefix (7B) + name (32B, no NUL) + recv_timestamp (4B LE) + path_len (1B) + path (Packet::writePath-encoded, variable length per path_len)
#define BEEBO_RESP_END_OF_ADVERT_PATHS 218  // last reply to GET_ADVERT_PATHS
#define BEEBO_RESP_PUBLIC_KEY          219  // reply to GET_PUBLIC_KEY: that role's 32-byte Ed25519 public key
#define BEEBO_RESP_BOARD_ID            220  // reply to GET_BOARD_ID: 6-byte eFuse base MAC
#define BEEBO_RESP_ROLE_SECRETS        221  // reply to UNLOCK_ROLE_SECRETS on a matching candidate: repeater.guest.password + NUL + node.wifi.password + NUL + repeater.password (any may be empty)
#define BEEBO_RESP_ROLE_NAME           222  // reply to GET_ROLE_NAME: that role's own name bytes (no NUL)
#define BEEBO_RESP_BOARD_NAME          223  // reply to GET_BOARD_NAME: board.name bytes (no NUL, may be empty)
#define BEEBO_RESP_REGION_DEFAULT      224  // reply to GET_REGION_DEFAULT: default-region name bytes (no NUL, may be empty)
